import ctypes as C,re,xml.etree.ElementTree as E
from pathlib import Path
c=C.CDLL('libcairo.so.2');ptr=C.c_void_p;D=C.c_double;I=C.c_int

def bind(n,r,args):f=getattr(c,'cairo_'+n);f.restype=r;f.argtypes=args;return f
surface=bind('image_surface_create',ptr,[I,I,I])(0,900,680)
ctx=bind('create',ptr,[ptr])(surface)
def fn(n,*vals):
 types=[ptr]+[I if isinstance(v,int) and n in ['select_font_face'] else D for v in vals]
 return bind(n,None,types)(ctx,*vals)
def color(h):fn('set_source_rgb',*[int(h[i:i+2],16)/255 for i in (0,2,4)])
def box(x,y,w,h,clr):color(clr);fn('rectangle',x,y,w,h);fn('fill')
def label(s,x,y,col='746b65'):
 color(col);bind('select_font_face',None,[ptr,C.c_char_p,I,I])(ctx,b'Arial',0,0);fn('set_font_size',11);fn('move_to',x,y);bind('show_text',None,[ptr,C.c_char_p])(ctx,s.encode())
def path(d):
 toks=re.findall(r'[MLCHVZ]|-?\\d+(?:\\.\\d+)?',d);i=0;x=y=0
 while i<len(toks):
  cmd=toks[i];i+=1
  if cmd=='Z':fn('close_path');continue
  num={'M':2,'L':2,'C':6,'H':1,'V':1}[cmd];v=list(map(float,toks[i:i+num]));i+=num
  if cmd in 'ML':fn('move_to' if cmd=='M' else 'line_to',*v);x,y=v
  elif cmd=='C':fn('curve_to',*v);x,y=v[-2:]
  elif cmd=='H':x=v[0];fn('line_to',x,y)
  elif cmd=='V':y=v[0];fn('line_to',x,y)
def draw(name,x,y,w,col=None):
 root=E.parse(name).getroot();view=list(map(float,root.attrib['viewBox'].split()));fn('save');fn('translate',x,y);fn('scale',w/view[2],w/view[2])
 def walk(el,fill='713f35'):
  fn('save')
  fill=el.attrib.get('fill',fill).lstrip('#')
  for op,args in re.findall(r'(translate|scale)\\((["'^)]*)'"\\)',el.attrib.get('transform','')):
   v=list(map(float,re.findall(r'-?\\d+(?:\\.\\d+)?',args)));fn(op,*((v+[0])[:2] if op=='translate' else (v+[v[0]])[:2]))
  if el.tag.endswith('path'):color(col or fill);path(el.attrib['d']);fn('fill')
  for ch in el:walk(ch,fill)
  fn('restore')
 walk(root);fn('restore')
box(0,0,900,680,'ffffff');box(0,245,900,245,'292321')
label('FERNWAY / PRIMARY',28,28);label('REVERSED',28,273,'cbb7aa')
draw('logo.svg',145,47,610);draw('logo-reversed.svg',145,292,610)
for x,w in [(70,96),(250,32),(365,16)]:draw('mark.svg',x,540+(96-w)/2,w);label(str(w)+' px',x,660)
box(498,566,205,40,'f1f1f1');draw('mark.svg',514,578,16);label('Fernway',540,590);label('Browser tab / actual size',498,660)
bind('surface_write_to_png',I,[ptr,C.c_char_p])(surface,b'/tmp/fernway-current/proof.png')
# Actual-size assets are also rendered separately for inspection.
for w in [16,32,128]:
 surface=bind('image_surface_create',ptr,[I,I,I])(0,w,w);ctx=bind('create',ptr,[ptr])(surface);box(0,0,w,w,'ffffff');draw('mark.svg',0,0,w);bind('surface_write_to_png',I,[ptr,C.c_char_p])(surface,f'/tmp/fernway-current/mark-{w}.png'.encode())
